// Members.txt starts as: Priya / Tomas / Keiko

OPENFILE "Members.txt" FOR APPEND
WRITEFILE "Members.txt", "Wen"
CLOSEFILE "Members.txt"
// Members.txt now: Priya / Tomas / Keiko / Wen   (4 lines)

OPENFILE "Members.txt" FOR WRITE
WRITEFILE "Members.txt", "Omar"
CLOSEFILE "Members.txt"
// Members.txt now: Omar   (1 line - the four earlier lines were erased)
